const formularioLogin=document.querySelector("#form-login"),mensagemLogin=document.querySelector("#mensagem-login"),botaoEntrar=document.querySelector(".botao-entrar");formularioLogin&&formularioLogin.addEventListener("submit",async o=>{o.preventDefault();const e=document.querySelector("#email").value.trim(),t=document.querySelector("#senha").value;mensagemLogin.textContent="",mensagemLogin.style.color="",botaoEntrar.disabled=!0,botaoEntrar.textContent="Entrando...";try{const o=await fetch("/api/auth/login",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({email:e,senha:t})}),n=await o.json();if(!o.ok)throw new Error(n.mensagem||"Não foi possível realizar o login.");sessionStorage.setItem("token",n.token),sessionStorage.setItem("usuario",JSON.stringify(n.usuario)),mensagemLogin.style.color="#25885b",mensagemLogin.textContent="Login realizado. Carregando painel...",window.setTimeout(()=>{window.location.href="/dashboard.html"},700)}catch(o){console.error("Erro no login:",o),mensagemLogin.style.color="#c34242",mensagemLogin.textContent=o.message||"Não foi possível realizar o login."}finally{botaoEntrar.disabled=!1,botaoEntrar.textContent="Entrar no sistema"}});